Good use case for Bull. Here's the worker:

```typescript
// src/workers/image.worker.ts
import { Job } from 'bull';
import sharp from 'sharp';
import { storage } from '../services/storage';

interface ImageJobData {
  fileId: string;
  sizes: { width: number; height: number; suffix: string }[];
}

export async function processImage(job: Job<ImageJobData>) {
  const { fileId, sizes } = job.data;
  const original = await storage.download(fileId);

  for (const size of sizes) {
    const resized = await sharp(original)
      .resize(size.width, size.height, { fit: 'inside' })
      .toBuffer();

    await storage.upload(`${fileId}_${size.suffix}`, resized);
    job.progress((sizes.indexOf(size) + 1) / sizes.length * 100);
  }

  return { processed: sizes.length };
}
```

