Here's a practical email validator:

```typescript
function isValidEmail(email: string): boolean {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
}
```

This handles 99% of real-world cases. If you need RFC 5322 compliance (which you probably don't), say so and I'll give you the 500-character regex monstrosity. What's this for - form validation, data import, or something else?

For production form validation with domain verification:

```typescript
import dns from 'dns/promises';

interface EmailValidation {
  valid: boolean;
  reason?: 'format' | 'domain' | 'mx';
}

async function validateEmail(email: string): Promise<EmailValidation> {
  // Format check
  const formatRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!formatRe.test(email)) {
    return { valid: false, reason: 'format' };
  }

  const domain = email.split('@')[1];

  // Domain exists check
  try {
    await dns.lookup(domain);
  } catch {
    return { valid: false, reason: 'domain' };
  }

  // MX record check (can receive email)
  try {
    const mx = await dns.resolveMx(domain);
    if (mx.length === 0) {
      return { valid: false, reason: 'mx' };
    }
  } catch {
    return { valid: false, reason: 'mx' };
  }

  return { valid: true };
}
```

This checks format, domain existence, and MX records. The MX check confirms the domain can actually receive email. Want me to add this to your form validation utils?

Added to your project:

**`src/utils/validation/email.ts`**
```typescript
import dns from 'dns/promises';

export interface EmailValidation {
  valid: boolean;
  reason?: 'format' | 'domain' | 'mx';
}

export async function validateEmail(email: string): Promise<EmailValidation> {
  const formatRe = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  if (!formatRe.test(email)) {
    return { valid: false, reason: 'format' };
  }

  const domain = email.split('@')[1];

  try {
    await dns.lookup(domain);
  } catch {
    return { valid: false, reason: 'domain' };
  }

  try {
    const mx = await dns.resolveMx(domain);
    if (mx.length === 0) {
      return { valid: false, reason: 'mx' };
    }
  } catch {
    return { valid: false, reason: 'mx' };
  }

  return { valid: true };
}
```

**`src/utils/validation/__tests__/email.test.ts`**
```typescript
import { validateEmail } from '../email';

describe('validateEmail', () => {
  it('rejects invalid format', async () => {
    const result = await validateEmail('notanemail');
    expect(result).toEqual({ valid: false, reason: 'format' });
  });

  it('rejects missing @', async () => {
    const result = await validateEmail('test.example.com');
    expect(result).toEqual({ valid: false, reason: 'format' });
  });

  it('rejects non-existent domain', async () => {
    const result = await validateEmail('test@thisdomain.doesnotexist.invalid');
    expect(result).toEqual({ valid: false, reason: 'domain' });
  });

  it('accepts valid email with MX records', async () => {
    const result = await validateEmail('test@gmail.com');
    expect(result).toEqual({ valid: true });
  });

  it('handles domain without MX records', async () => {
    // example.com exists but has no MX
    const result = await validateEmail('test@example.com');
    expect(result.reason).toBe('mx');
  });
});
```

