Two universal concerns: permissions and cart. Here's the architecture:

**1. Permissions store with selectors:**

```typescript
// src/stores/permissions.store.ts
import { create } from 'zustand';

interface Permission {
  resource: string;
  actions: ('read' | 'write' | 'delete')[];
}

interface PermissionsStore {
  permissions: Permission[];
  setPermissions: (perms: Permission[]) => void;

  // Computed selectors
  can: (resource: string, action: string) => boolean;
  canAny: (resource: string) => boolean;
}

export const usePermissions = create<PermissionsStore>((set, get) => ({
  permissions: [],
  setPermissions: (permissions) => set({ permissions }),

  can: (resource, action) => {
    const perm = get().permissions.find(p => p.resource === resource);
    return perm?.actions.includes(action as any) ?? false;
  },

  canAny: (resource) => {
    return get().permissions.some(p => p.resource === resource);
  },
}));

// Usage in any feature:
const canEditOrders = usePermissions(s => s.can('orders', 'write'));
```

**2. Cart store with persistence:**

```typescript
// src/stores/cart.store.ts
import { create } from 'zustand';
import { persist } from 'zustand/middleware';

interface CartItem {
  productId: string;
  quantity: number;
  price: number;
}

interface CartStore {
  items: CartItem[];

  // Actions
  addItem: (item: CartItem) => void;
  removeItem: (productId: string) => void;
  updateQuantity: (productId: string, quantity: number) => void;
  clear: () => void;

  // Computed
  total: () => number;
  itemCount: () => number;
}

export const useCart = create<CartStore>()(
  persist(
    (set, get) => ({
      items: [],

      addItem: (item) => set(state => {
        const existing = state.items.find(i => i.productId === item.productId);
        if (existing) {
          return {
            items: state.items.map(i =>
              i.productId === item.productId
                ? { ...i, quantity: i.quantity + item.quantity }
                : i
            )
          };
        }
        return { items: [...state.items, item] };
      }),

      removeItem: (productId) => set(state => ({
        items: state.items.filter(i => i.productId !== productId)
      })),

      updateQuantity: (productId, quantity) => set(state => ({
        items: quantity <= 0
          ? state.items.filter(i => i.productId !== productId)
          : state.items.map(i =>
              i.productId === productId ? { ...i, quantity } : i
            )
      })),

      clear: () => set({ items: [] }),

      total: () => get().items.reduce((sum, i) => sum + i.price * i.quantity, 0),
      itemCount: () => get().items.reduce((sum, i) => sum + i.quantity, 0),
    }),
    { name: 'cart-storage' } // Persists to localStorage
  )
);
```

**3. Permission-aware cart hook:**

```typescript
// src/shared/hooks/useAuthorizedCart.ts
export function useAuthorizedCart() {
  const cart = useCart();
  const canCheckout = usePermissions(s => s.can('orders', 'write'));

  return {
    ...cart,
    canCheckout,
    checkout: canCheckout ? cart.checkout : undefined,
  };
}
```

**4. Provider setup:**

```typescript
