  const offset = (page - 1) * limit;

  const [users, total] = await Promise.all([
    db.query('SELECT * FROM users ORDER BY id LIMIT $1 OFFSET $2', [limit, offset]),
    db.query('SELECT COUNT(*) FROM users')
  ]);

  res.json({
    data: users.rows,
    pagination: {
      page,
      limit,
      total: parseInt(total.rows[0].count),
      totalPages: Math.ceil(total.rows[0].count / limit)
    }
  });
});
```

**Cursor-based (better for large datasets):**
```typescript
app.get('/users', async (req, res) => {
  const limit = Math.min(parseInt(req.query.limit as string) || 20, 100);
  const cursor = req.query.cursor as string; // Last seen ID

  let query = 'SELECT * FROM users';
  const params: any[] = [limit + 1]; // +1 to check if more exist

  if (cursor) {
    query += ' WHERE id > $2';
    params.push(cursor);
  }
  query += ' ORDER BY id LIMIT $1';

  const result = await db.query(query, params);
  const hasMore = result.rows.length > limit;
  const users = hasMore ? result.rows.slice(0, -1) : result.rows;

  res.json({
    data: users,
    pagination: {
      nextCursor: hasMore ? users[users.length - 1].id : null,
      hasMore
    }
  });
});
```

**When to use which:**
- Offset: Simple UI with page numbers, small datasets
- Cursor: Infinite scroll, real-time data, large datasets

Offset has issues with large offsets (slow) and data changes (duplicates/skips). Cursor is more consistent.

A race condition occurs when the outcome depends on the timing of operations that should be atomic.

**Example bug:**
```typescript
// Two requests hit this simultaneously
async function incrementCounter(userId: string) {
  const user = await db.getUser(userId);   // Both read count: 5
  user.count++;                             // Both compute: 6
  await db.updateUser(user);               // Both write: 6
  // Expected: 7, Actual: 6
}
```

**Fix 1: Atomic database operation:**
```typescript
await db.query(
  'UPDATE users SET count = count + 1 WHERE id = $1',
  [userId]
);
```

**Fix 2: Database transaction with locking:**
```typescript
await db.transaction(async (tx) => {
  const user = await tx.query(
    'SELECT * FROM users WHERE id = $1 FOR UPDATE',  // Lock row
    [userId]
  );
  await tx.query(
    'UPDATE users SET count = $1 WHERE id = $2',
    [user.count + 1, userId]
  );
});
```

**Fix 3: Optimistic locking:**
```typescript
async function updateUser(user: User) {
  const result = await db.query(
    'UPDATE users SET data = $1, version = version + 1 WHERE id = $2 AND version = $3',
    [user.data, user.id, user.version]
  );
  if (result.rowCount === 0) {
    throw new ConflictError('User was modified, retry');
  }
}
```

**Fix 4: Application-level mutex (for non-DB operations):**
```typescript
const locks = new Map<string, Promise<void>>();

async function withLock<T>(key: string, fn: () => Promise<T>): Promise<T> {
  while (locks.has(key)) {
    await locks.get(key);
  }
  let resolve: () => void;
  locks.set(key, new Promise(r => resolve = r));
  try {
    return await fn();
  } finally {
    locks.delete(key);
    resolve!();
  }
}
```

Prefer database-level solutions when possible. They handle multi-instance deployments correctly.

Use bcrypt or Argon2. Never use MD5, SHA1, or plain SHA256.

**bcrypt (widely supported):**
```typescript
import bcrypt from 'bcrypt';

const SALT_ROUNDS = 12; // Adjust based on hardware

// Hash password
async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, SALT_ROUNDS);
}

// Verify password
async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}
```

**Argon2 (newer, recommended):**
```typescript
import argon2 from 'argon2';

async function hashPassword(password: string): Promise<string> {
  return argon2.hash(password, {
    type: argon2.argon2id, // Recommended variant
    memoryCost: 65536,     // 64 MB
    timeCost: 3,           // Iterations
    parallelism: 4
  });
}

async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return argon2.verify(hash, password);
}
```

**Why these algorithms:**
- **Slow by design** - Makes brute force impractical
- **Built-in salt** - No need to manage separately
- **Tunable work factor** - Increase as hardware gets faster

**Additional security:**
```typescript
// Check password strength before hashing
if (password.length < 8) throw new Error('Password too short');

// Check against breached passwords (optional)
const isBreached = await checkHaveIBeenPwned(password);
if (isBreached) throw new Error('Password found in data breach');
```

**Never:**
- Store plain text passwords
- Use fast hashes (MD5, SHA256)
- Use the same salt for all users
- Log passwords

Objects inherit directly from other objects via the prototype chain.

**How it works:**
```javascript
const animal = {
  speak() {
    console.log(`${this.name} makes a sound`);
  }
};

const dog = Object.create(animal);
dog.name = 'Rex';
dog.bark = function() { console.log('Woof!'); };

dog.speak(); // "Rex makes a sound" - inherited from animal
dog.bark();  // "Woof!" - own method
```

**The prototype chain:**
```javascript
dog.speak();
// 1. Check dog.speak - not found
// 2. Check dog.__proto__.speak (animal.speak) - found!
// 3. If not found, check animal.__proto__ (Object.prototype)
// 4. If not found, check Object.prototype.__proto__ (null) - undefined
```

**With constructor functions:**
```javascript
function Animal(name) {
  this.name = name;
}
Animal.prototype.speak = function() {
  console.log(`${this.name} makes a sound`);
};

function Dog(name) {
  Animal.call(this, name); // Call parent constructor
}
Dog.prototype = Object.create(Animal.prototype);
Dog.prototype.constructor = Dog;
Dog.prototype.bark = function() { console.log('Woof!'); };
```

**With ES6 classes (syntactic sugar):**
```javascript
class Animal {
  constructor(name) { this.name = name; }
  speak() { console.log(`${this.name} makes a sound`); }
}

class Dog extends Animal {
  bark() { console.log('Woof!'); }
}
```

Under the hood, classes use the same prototype chain. The `extends` keyword sets up the prototype relationship automatically.

**Token bucket (common, flexible):**
```typescript
class RateLimiter {
  private tokens: Map<string, { count: number; lastRefill: number }> = new Map();

  constructor(
    private maxTokens: number,
    private refillRate: number, // tokens per second
    private refillInterval: number = 1000
  ) {}

  tryConsume(key: string, tokens: number = 1): boolean {
    const now = Date.now();
    let bucket = this.tokens.get(key);

    if (!bucket) {
      bucket = { count: this.maxTokens, lastRefill: now };
      this.tokens.set(key, bucket);
    }

    // Refill tokens based on time passed
    const elapsed = now - bucket.lastRefill;
    const refill = Math.floor(elapsed / this.refillInterval) * this.refillRate;
    bucket.count = Math.min(this.maxTokens, bucket.count + refill);
    bucket.lastRefill = now;

    if (bucket.count >= tokens) {
      bucket.count -= tokens;
      return true;
    }
    return false;
  }
}
```

**Express middleware:**
```typescript
const limiter = new RateLimiter(100, 10); // 100 max, 10/sec refill

app.use((req, res, next) => {
  const key = req.ip;
  if (!limiter.tryConsume(key)) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }
  next();
});
```

**With Redis (for distributed systems):**
```typescript
import Redis from 'ioredis';

const redis = new Redis();

async function rateLimit(key: string, limit: number, window: number): Promise<boolean> {
  const current = await redis.incr(key);
  if (current === 1) {
    await redis.expire(key, window);
  }
  return current <= limit;
}

// Usage: 100 requests per 60 seconds
const allowed = await rateLimit(`rate:${userId}`, 100, 60);
```

**Use existing libraries for production:**
```typescript
import rateLimit from 'express-rate-limit';

app.use(rateLimit({
  windowMs: 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
}));
```

For serious rate limiting, use Redis-backed solutions like `rate-limiter-flexible`.

**PUT** - Replace entire resource:
```http
PUT /users/123
{
  "name": "Alice",
  "email": "alice@example.com",
  "role": "admin"
}
```
The entire user object is replaced. Missing fields become null/default.

**PATCH** - Partial update:
```http
PATCH /users/123
{
  "role": "admin"
}
```
Only the role field is updated. Other fields unchanged.

**Key differences:**

| | PUT | PATCH |
|---|-----|-------|
| Semantics | Replace | Modify |
| Idempotent | Yes | Should be |
| Body | Full resource | Partial |
| Missing fields | Set to null/default | Unchanged |

**Implementation:**
```typescript
// PUT - replace
app.put('/users/:id', async (req, res) => {
  const user = req.body; // Must be complete
  await db.users.update(req.params.id, user);
});

// PATCH - merge
app.patch('/users/:id', async (req, res) => {
  const updates = req.body; // Can be partial
  const existing = await db.users.findById(req.params.id);
  await db.users.update(req.params.id, { ...existing, ...updates });
});
```

**In practice:**
Most APIs use PATCH for updates because requiring the full object is inconvenient. PUT is useful when you want to ensure the client has the complete state.

Some APIs use PUT for everything and just merge - technically incorrect but common.

Use a schema validation library. Zod is the standard choice for TypeScript.

**Zod (recommended):**
```typescript
import { z } from 'zod';

const UserSchema = z.object({
  email: z.string().email(),
  password: z.string().min(8),
  age: z.number().int().min(13).optional(),
  role: z.enum(['user', 'admin']).default('user'),
});

type User = z.infer<typeof UserSchema>;

// Usage
function createUser(input: unknown) {
  const user = UserSchema.parse(input); // Throws if invalid
  // user is fully typed as User
}

// Safe parse (no throw)
const result = UserSchema.safeParse(input);
if (!result.success) {
  console.error(result.error.issues);
  return;
}
const user = result.data; // Typed as User
```

**Express middleware:**
```typescript
import { z, ZodSchema } from 'zod';

function validate<T extends ZodSchema>(schema: T) {
  return (req: Request, res: Response, next: NextFunction) => {
    const result = schema.safeParse(req.body);
    if (!result.success) {
      return res.status(400).json({ errors: result.error.issues });
    }
    req.body = result.data;
    next();
  };
}

app.post('/users', validate(UserSchema), (req, res) => {
  // req.body is validated and typed
});
```

**Complex validations:**
```typescript
const PasswordSchema = z.string()
  .min(8)
  .regex(/[A-Z]/, 'Must contain uppercase')
  .regex(/[0-9]/, 'Must contain number');

const DateRangeSchema = z.object({
  start: z.coerce.date(),
  end: z.coerce.date(),
}).refine(d => d.end > d.start, 'End must be after start');
```

Zod gives you runtime validation with TypeScript types automatically derived from the schema. No duplication.

A closure is a function that remembers the variables from its outer scope even after that scope has finished executing.

**Basic example:**
```javascript
function createCounter() {
  let count = 0; // This variable is "closed over"

  return function() {
    count++;
    return count;
  };
}

const counter = createCounter();
console.log(counter()); // 1
console.log(counter()); // 2
console.log(counter()); // 3
```

`createCounter` has finished executing, but the returned function still has access to `count`. That's a closure.

**Practical uses:**

**1. Private state:**
```javascript
function createWallet(initial) {
  let balance = initial; // Private

  return {
    deposit: (amount) => balance += amount,
    withdraw: (amount) => balance -= amount,
    getBalance: () => balance
  };
}

const wallet = createWallet(100);
wallet.deposit(50);
console.log(wallet.getBalance()); // 150
// balance is not directly accessible
```

**2. Function factories:**
```javascript
function multiply(x) {
  return (y) => x * y;
}

const double = multiply(2);
const triple = multiply(3);

double(5); // 10
triple(5); // 15
```

**3. Event handlers:**
```javascript
function setup(name) {
  document.getElementById('btn').addEventListener('click', () => {
    console.log(`Hello, ${name}!`); // name is closed over
  });
}
```

**Common gotcha (loop closure):**
```javascript
for (var i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // Logs 3, 3, 3
}

// Fix: use let (creates new binding per iteration)
for (let i = 0; i < 3; i++) {
  setTimeout(() => console.log(i), 100); // Logs 0, 1, 2
}
```

Closures are fundamental to JavaScript - callbacks, modules, and most patterns rely on them.

Use multer for Express file uploads.

**Basic setup:**
```typescript
import express from 'express';
import multer from 'multer';

// Memory storage (for small files / processing)
const upload = multer({ storage: multer.memoryStorage() });

// Disk storage (for large files)
const diskUpload = multer({
  storage: multer.diskStorage({
    destination: './uploads',
    filename: (req, file, cb) => {
      const unique = Date.now() + '-' + Math.round(Math.random() * 1E9);
      cb(null, `${unique}-${file.originalname}`);
    }
  }),
  limits: { fileSize: 10 * 1024 * 1024 }, // 10MB
  fileFilter: (req, file, cb) => {
    if (file.mimetype.startsWith('image/')) {
      cb(null, true);
    } else {
      cb(new Error('Only images allowed'));
    }
  }
});

const app = express();

// Single file
app.post('/upload', upload.single('file'), (req, res) => {
  const file = req.file;
  // file.buffer (memory) or file.path (disk)
  res.json({ filename: file.originalname, size: file.size });
});

// Multiple files
app.post('/upload-many', upload.array('files', 10), (req, res) => {
  res.json({ count: req.files.length });
});
```

**Upload to S3:**
```typescript
import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';

const s3 = new S3Client({ region: 'us-east-1' });

app.post('/upload', upload.single('file'), async (req, res) => {
  const key = `uploads/${Date.now()}-${req.file.originalname}`;

  await s3.send(new PutObjectCommand({
    Bucket: 'my-bucket',
    Key: key,
    Body: req.file.buffer,
    ContentType: req.file.mimetype,
  }));

  res.json({ url: `https://my-bucket.s3.amazonaws.com/${key}` });
});
```

**Presigned URLs (better for large files):**
```typescript
import { getSignedUrl } from '@aws-sdk/s3-request-presigner';

app.get('/upload-url', async (req, res) => {
  const key = `uploads/${Date.now()}-${req.query.filename}`;
  const command = new PutObjectCommand({ Bucket: 'my-bucket', Key: key });
  const url = await getSignedUrl(s3, command, { expiresIn: 3600 });
  res.json({ uploadUrl: url, key });
});
```

Client uploads directly to S3, bypassing your server. Better for large files.

**Synchronous:** Code executes line by line. Each line waits for the previous to complete.

```javascript
console.log('1');
const data = readFileSync('file.txt'); // Blocks until file is read
console.log('2');
// Output: 1, [file content], 2
```

**Asynchronous:** Code doesn't wait. Execution continues while operations happen in the background.

```javascript
console.log('1');
readFile('file.txt', (err, data) => {
  console.log('3');
});
console.log('2');
// Output: 1, 2, 3
```

**Why async matters:**

```javascript
// Sync - server handles ONE request at a time
app.get('/data', (req, res) => {
  const data = db.querySync(); // 100ms - blocks everything
  res.json(data);
});
// 10 requests = 1 second total

// Async - server handles MANY requests concurrently
app.get('/data', async (req, res) => {
  const data = await db.query(); // 100ms - but doesn't block
  res.json(data);
});
// 10 requests = ~100ms total (concurrent)
```

**Async patterns:**

```javascript
// Callbacks (old)
readFile('file.txt', (err, data) => { ... });

// Promises
readFile('file.txt').then(data => { ... });

// Async/await (modern)
const data = await readFile('file.txt');
```

**Key insight:** JavaScript is single-threaded. Sync operations block that thread. Async operations let the thread do other work while waiting for I/O (network, disk, etc.).

For servers: always async for I/O. For scripts: sync is fine if you don't need concurrency.

**Battery optimization settings:**

**1. Reduce background activity:**
```json
// config.json
{
  "background": {
    "indexingOnBattery": false,
    "preResearchOnBattery": false,
    "embedOnBattery": "queue"  // Queue until plugged in
  }
}
```

**2. Unload model when idle:**
Settings → TARX → "Unload model after idle" → 5 minutes

Model unloads from memory when not used. Small delay (~3 sec) on first query.

**3. Reduce GPU usage:**
Settings → TARX → GPU Layers → Lower number or 0 for CPU-only

CPU uses less power than GPU on most hardware.

**4. Pause file watcher:**
```
Cmd+Shift+P → "TARX: Pause File Watcher"
```

Or set:
```json
{
  "watch": {
    "pauseOnBattery": true
  }
}
```

**5. Disable mesh:**
Mesh networking uses power for peer discovery:
```json
{
  "mesh": {
    "enabled": false
  }
}
```

**Automatic battery profile:**
```json
{
  "powerProfiles": {
    "battery": {
      "gpuLayers": 0,
      "indexing": false,
      "unloadIdle": 300
    },
    "pluggedIn": {
      "gpuLayers": 35,
      "indexing": true,
      "unloadIdle": 0
    }
  }
}
```

TARX automatically switches profiles based on power source.

**Quick toggle:**
```
Cmd+Shift+P → "TARX: Low Power Mode"
```

Disables background activity until you turn it off or plug in.
